struct WindowDeleter {
    void operator()(SDL_Window* p) const noexcept { SDL_DestroyWindow(p); }
};
using WindowOwner = std::unique_ptr<SDL_Window, WindowDeleter>;

struct Resources {
    SdlRuntime runtime;  // 마지막에 정리
    WindowOwner window;  // runtime보다 먼저 정리
    // 시간과 종료 상태는 전체 코드에서 이어진다.
};

auto candidate = std::make_unique<Resources>();
// SDL 상태 확인 → 창 획득 → 주파수 확인
// 실패하면 return false; candidate가 정리된다.
active = std::move(candidate);
return true;
